/// <summary>
/// N.Freidenberger 16.01.2025
/// </summary>
/// <returns>int</returns>
int  active()
{
    FormRun     formRun = this.formRun();
    AVAEDIAddress   avaEDIAddress = this.cursor();
    int ret = next active();
    FormControl  contractBtn = formRun.design().controlName(formControlStr(SalesTable,AVAEDIBuyerContactCreate));
    contractBtn.enabled(avaEDIAddress.EDIAddressType == AVAEDIAddressType::Buyer);
    return ret;
}
